fn utc(y: i32, mo: u32, d: u32, h: u32, mi: u32, s: u32) -> DateTime<Utc> {
    Utc.with_ymd_and_hms(y, mo, d, h, mi, s).single().unwrap()
}

fn pdt(dt: DateTime<Utc>) -> PyDateTime {
    PyDateTime::from_utc(dt)
}

fn golden(name: &str) -> Value {
    let text = match name {
        "classify_fixed" => GOLDEN_CLASSIFY_FIXED,
        "dates" => GOLDEN_DATES,
        "feeds" => GOLDEN_FEEDS,
        "llm" => GOLDEN_LLM,
        _ => unreachable!(),
    };
    serde_json::from_str(text).unwrap()
}

fn hits_json(text: &str) -> Value {
    serde_json::to_value(classify_text(text)).unwrap()
}

/// Compare numbers by value (Python writes 1.0 where an int may come back), everything else exactly.
fn same(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Number(x), Value::Number(y)) => x.as_f64() == y.as_f64(),
        (Value::Array(x), Value::Array(y)) => x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same(p, q)),
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|((k1, v1), (k2, v2))| k1 == k2 && same(v1, v2))
        }
        _ => a == b,
    }
}

// =========================================================================== parity goldens

#[test]
fn golden_feeds_parse_like_feedparser() {
    for (i, f) in golden("feeds").as_array().unwrap().iter().enumerate() {
        let xml = f["xml"].as_str().unwrap();
        let items = if f["kind"] == "rotowire" { news::parse_rotowire(xml) } else { news::parse_espn_news(xml) };
        let got: Vec<Value> = items.iter().map(|it| Value::Object(it.model_dump_json())).collect();
        let want = f["items"].as_array().unwrap();
        assert_eq!(got.len(), want.len(), "feed {i}");
        for (g, w) in got.iter().zip(want) {
            assert!(same(g, w), "feed {i}\n got {g}\nwant {w}");
        }
    }
}

#[test]
fn golden_parse_rss_date() {
    for d in golden("dates").as_array().unwrap() {
        let raw = d["raw"].as_str().unwrap();
        let got = news::parse_rss_date(Some(raw)).map(|p| p.isoformat());
        assert_eq!(got.as_deref(), d["utc"].as_str(), "{raw:?}");
    }
    assert_eq!(news::parse_rss_date(None), None);
}

#[test]
fn golden_classify_text_fixture_items_and_targeted_corpus() {
    let g = golden("classify_fixed");
    let mut n = 0;
    for case in g.as_array().unwrap() {
        let text = case["text"].as_str().unwrap();
        let got = hits_json(text);
        assert!(same(&got, &case["hits"]), "{text:?}\n got {got}\nwant {}", case["hits"]);
        n += 1;
    }
    assert!(n > 300);
}

#[test]
fn golden_classify_text_every_stored_news_item() {
    // the tracked data-dir news store (the same items the parity dump ran with)
    let p = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../parity/fixtures/_datadir/news_items.json");
    let raw: Map<String, Value> = serde_json::from_str(&std::fs::read_to_string(p).unwrap()).unwrap();
    let fixed: Map<String, Value> = golden("classify_fixed")
        .as_array()
        .unwrap()
        .iter()
        .map(|c| (c["text"].as_str().unwrap().to_string(), c["hits"].clone()))
        .collect();
    for d in raw.values() {
        let it: NewsItem = serde_json::from_value(d.clone()).unwrap();
        let text = nr::item_text(&it);
        let want = fixed.get(&text).unwrap_or_else(|| panic!("no golden for {text:?}"));
        assert!(same(&hits_json(&text), want), "{text:?}");
    }
}

fn golden_dir() -> Option<std::path::PathBuf> {
    std::env::var_os("FM_NEWS_GOLDEN_DIR").map(Into::into).filter(|p: &std::path::PathBuf| p.exists())
}

#[test]
fn golden_fuzz_corpus_when_available() {
    let Some(dir) = golden_dir() else {
        eprintln!("FM_NEWS_GOLDEN_DIR not set: fuzz corpus skipped");
        return;
    };
    let cases: Vec<Value> = serde_json::from_str(&std::fs::read_to_string(dir.join("classify_fuzz.json")).unwrap()).unwrap();
    let mut bad = 0;
    for case in &cases {
        let text = case["text"].as_str().unwrap();
        if !same(&hits_json(text), &case["hits"]) {
            bad += 1;
            if bad < 5 {
                eprintln!("MISMATCH {text:?}\n got {}\nwant {}", hits_json(text), case["hits"]);
            }
        }
    }
    let tags: Vec<Value> = serde_json::from_str(&std::fs::read_to_string(dir.join("tags.json")).unwrap()).unwrap();
    for case in &tags {
        let text = case["text"].as_str().unwrap();
        let got = news::tag_text(&[Some(text)]);
        if json!(got) != case["tags"] {
            bad += 1;
            eprintln!("TAG MISMATCH {text:?} {got:?} {}", case["tags"]);
        }
    }
    assert_eq!(bad, 0, "{} classify cases, {} tag cases", cases.len(), tags.len());
}

// =========================================================================== test_news.py

fn fixture(name: &str) -> String {
    std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/news").join(name)).unwrap()
}

fn fake_fetch(url: &str, _p: Option<&fm_http::Params>) -> anyhow::Result<String> {
    Ok(match url {
        news::ROTOWIRE_URL => fixture("rotowire.xml"),
        news::ESPN_NEWS_URL => fixture("espn.xml"),
        _ => anyhow::bail!("unknown url"),
    })
}

#[test]
fn rotowire_parsing() {
    let items = news::fetch_rotowire(Some(&fake_fetch)).unwrap();
    assert_eq!(items.len(), 5);
    let faber = &items[0];
    assert_eq!(faber.source, "rotowire");
    assert_eq!(faber.player_name.as_deref(), Some("Brock Faber"));
    assert_eq!(faber.headline, "Begins season on IR");
    assert!(faber.blurb.starts_with("Faber (upper body) will begin"));
    assert!(!faber.blurb.contains("Visit RotoWire.com"));
    assert_eq!(faber.url.as_deref(), Some("https://www.rotowire.com/hockey/player/brock-faber-6317"));
    assert_eq!(faber.published, Some(pdt(utc(2026, 9, 28, 21, 38, 0))));
    for t in ["injury", "ir", "upper-body"] {
        assert!(faber.tags.contains(&t.to_string()));
    }
    assert_eq!(faber.id.as_deref(), Some("nhl594131"));
    let by: Map<String, &NewsItem> = items.iter().map(|i| (i.player_name.clone().unwrap(), i)).collect();
    assert!(by["Matthew Knies"].tags.contains(&"trade".to_string()));
    assert!(by["Elvis Merzlikins"].tags.contains(&"trade".to_string()));
}

#[test]
fn espn_parsing_and_fetch_all_sorted_and_resilient() {
    let items = news::fetch_espn_news(Some(&fake_fetch)).unwrap();
    let first = &items[0];
    assert!(first.source == "espn" && first.player_name.is_none());
    assert!(first.headline.starts_with("NHL season preview"));
    assert!(first.url.as_deref().unwrap().starts_with("https://www.espn.com/"));
    assert_eq!(first.published, Some(pdt(utc(2026, 9, 28, 14, 42, 14))));

    let all = news::fetch_all_news(Some(&fake_fetch));
    let sources: std::collections::HashSet<&str> = all.iter().map(|i| i.source.as_str()).collect();
    assert_eq!(sources.len(), 2);
    let dates: Vec<_> = all.iter().filter_map(|i| i.published.and_then(|p| p.to_utc())).collect();
    assert!(dates.windows(2).all(|w| w[0] >= w[1]));
    let broken = |url: &str, p: Option<&fm_http::Params>| {
        if url == news::ESPN_NEWS_URL {
            anyhow::bail!("boom")
        }
        fake_fetch(url, p)
    };
    let only = news::fetch_all_news(Some(&broken));
    assert!(!only.is_empty() && only.iter().all(|i| i.source == "rotowire"));
}

