// =========================================================================== test_news_roles.py

fn kinds(text: &str) -> std::collections::BTreeSet<(String, i64)> {
    classify_text(text).into_iter().map(|f| (f.kind, f.direction)).collect()
}

#[test]
fn pattern_table() {
    let cases: Vec<(&str, Vec<(&str, i64)>)> = vec![
        ("Skating on top line. Stenberg skated on the top line with Macklin Celebrini and Will Smith at practice.", vec![("top_line", 1)]),
        ("Stenberg was on the first power-play unit during Tuesday's practice.", vec![("pp1", 1)]),
        ("Demidov is quarterbacking PP1 and saw time on the top line in the exhibition finale.", vec![("pp1", 1), ("top_line", 1)]),
        ("Stenberg is expected to make the opening-night roster, per Curtis Pashelka of the Mercury News.", vec![("nhl_roster", 1)]),
        ("Stenberg was named to the Sharks' opening-night roster Monday.", vec![("nhl_roster", 1)]),
        ("The Blackhawks recalled Frondell from AHL Rockford on Sunday.", vec![("nhl_roster", 1)]),
        ("Hutson will skate on the top pairing alongside Mike Matheson.", vec![("first_line_pairing", 1)]),
        ("He will skate on the second line and see time on PP2.", vec![("extended_role", 1), ("pp2", 1)]),
        ("Knight is expected to defend the road net against the Golden Knights on Tuesday.", vec![("starter", 1)]),
        ("Andersen was activated from injured reserve Tuesday.", vec![("injury", 1)]),
        ("Frondell will start the season in the AHL with Rockford.", vec![("ahl_demotion", -1)]),
        ("The Blues assigned Snuggerud to AHL Springfield on Sunday.", vec![("ahl_demotion", -1)]),
        ("Iginla was returned to junior. He was sent back to Kelowna of the WHL on Monday.", vec![("junior_return", -1)]),
        ("Stenberg was loaned to Frolunda of the SHL for the season.", vec![("junior_return", -1)]),
        ("Demidov was a healthy scratch Thursday against Boston.", vec![("scratched", -1)]),
        ("Smith has been bumped from the top line and will skate on the third line.", vec![("top_line", -1)]),
        ("Catton was dropped to the second power-play unit.", vec![("pp1", -1)]),
        ("Michkov is unlikely to make the roster out of camp.", vec![("nhl_roster", -1)]),
        ("Faber (upper body) will begin the 2026-27 regular season on injured reserve.", vec![("injury", -1)]),
        ("Penguins general manager Kyle Dubas said he's not doing this day-to-day, year-to-year thing with Geno.", vec![]),
        ("Hurricanes, Panthers, Avs favored to win 2027 Stanley Cup.", vec![]),
        ("Smith is filling in for the injured Faber on the top line.", vec![("top_line", 1)]),
    ];
    for (text, want) in cases {
        let want: std::collections::BTreeSet<(String, i64)> = want.into_iter().map(|(k, d)| (k.to_string(), d)).collect();
        assert_eq!(kinds(text), want, "{text}");
    }
}

#[test]
fn every_rule_kind_is_known_and_has_a_note() {
    for r in nr::role_rules() {
        assert!(nr::KINDS.contains(&r.kind));
        assert!(!r.note.is_empty() && (-1..=1).contains(&r.direction) && r.confidence > 0.0 && r.confidence <= 1.0);
    }
}

#[test]
fn modifiers_and_overlap() {
    let f = &classify_text("Hutson is competing for a spot on the top pairing.")[0];
    assert_eq!((f.kind.as_str(), f.direction, f.ambiguous), ("first_line_pairing", 1, true));
    assert!((f.confidence - 0.8 * 0.6).abs() < 1e-9);
    let f = &classify_text("Coach said Demidov will not be scratched Thursday.")[0];
    assert_eq!((f.kind.as_str(), f.direction, f.ambiguous), ("scratched", 0, true));
    let fs = classify_text("Faber was placed on injured reserve. Two weeks later he was activated from injured reserve.");
    assert_eq!(fs.iter().map(|f| (f.kind.as_str(), f.direction)).collect::<Vec<_>>(), vec![("injury", 1)]);
    assert_eq!(fs[0].quote, "Two weeks later he was activated from injured reserve.");
    assert!(fs[0].ambiguous);
}

const PUB: fn() -> DateTime<Utc> = || utc(2026, 9, 28, 18, 0, 0);

fn ritem(i: u32, player: Option<&str>, headline: &str, blurb: &str, source: &str) -> NewsItem {
    NewsItem {
        source: source.into(),
        id: Some(format!("n{i}")),
        player_name: player.map(String::from),
        headline: headline.into(),
        blurb: blurb.into(),
        url: None,
        published: Some(pdt(PUB())),
        tags: news::tag_text(&[Some(headline), Some(blurb)]),
    }
}

#[test]
fn extract_role_signals_keeps_item_metadata() {
    let items = vec![
        ritem(1, Some("Ivar Stenberg"), "Skating on top line", "Stenberg skated on the top line on Monday.", "rotowire"),
        ritem(2, None, "Sharks notes", "Nothing about roles here.", "espn"),
    ];
    let sigs = nr::extract_role_signals(&items, None, None, nr::LLM_BATCH, now0());
    assert_eq!(sigs.len(), 1);
    let s = &sigs[0];
    assert_eq!(
        (s.player_name.as_deref(), s.kind.as_str(), s.direction, s.source.as_str(), s.item_id.as_deref(), s.origin.as_str()),
        (Some("Ivar Stenberg"), "top_line", 1, "rotowire", Some("n1"), "rules")
    );
    assert_eq!(s.published, Some(pdt(PUB())));
    assert!(s.quote.contains("top line") && s.label() == "top_line+" && s.when() == "2026-09-28");
}

