fn approx(a: f64, b: f64, tol: f64) -> bool {
    (a - b).abs() <= tol
}

#[test]
fn moneyline_math() {
    assert!(approx(o::american_to_prob(-150.0).unwrap(), 0.6, 1e-12));
    assert!(approx(o::american_to_prob(150.0).unwrap(), 0.4, 1e-12));
    assert!(approx(o::american_to_prob(100.0).unwrap(), 0.5, 1e-12));
    assert!(approx(o::american_to_prob(-110.0).unwrap(), 110.0 / 210.0, 1e-12));
    for bad in [0.0, 50.0, -99.0] {
        assert!(o::american_to_prob(bad).is_err());
    }
    for price in [-250, -150, -110, 100, 120, 300] {
        assert_eq!(o::prob_to_american(o::american_to_prob(price as f64).unwrap()).unwrap(), price);
    }
    let (h, a) = o::no_vig(o::american_to_prob(-110.0).unwrap(), o::american_to_prob(-110.0).unwrap()).unwrap();
    assert!(approx(h, 0.5, 1e-12) && approx(a, 0.5, 1e-12));
    let (h, a) = o::no_vig(0.6, 0.45).unwrap();
    assert!(approx(h, 0.6 / 1.05, 1e-12) && approx(h + a, 1.0, 1e-12));
}

#[test]
fn team_total_split_and_expected_total() {
    let (h, a) = o::split_total(6.0, 0.5).unwrap();
    assert!(approx(h, 3.0, 1e-6) && approx(a, 3.0, 1e-6));
    let (h, a) = o::split_total(6.0, 0.65).unwrap();
    assert!(approx(h + a, 6.0, 1e-9) && h > 3.3 && a < 2.7);
    assert!(approx(o::win_probability(h, a), 0.65, 1e-6));
    let (h2, a2) = o::split_total(6.0, 0.35).unwrap();
    assert!(approx(h2, a, 1e-6) && approx(a2, h, 1e-6));
    let shares: Vec<f64> = [0.3, 0.45, 0.55, 0.7, 0.8].iter().map(|p| o::split_total(6.5, *p).unwrap().0).collect();
    assert!(shares.windows(2).all(|w| w[0] <= w[1]));
    assert!(o::split_total(0.0, 0.5).is_err());
    assert_eq!(o::expected_total(5.5, None), 5.5);
    let even = o::expected_total(6.5, Some(0.5));
    assert!(6.5 < even && even < 6.8);
    assert!(o::expected_total(6.5, Some(0.4)) < even && even < o::expected_total(6.5, Some(0.6)));
    let e6 = o::expected_total(6.0, Some(0.5));
    assert!(5.9 < e6 && e6 < 6.3);
}

