#[test]
fn parse_fixture_and_quota() {
    let (games, warnings) = o::parse_events(&events(), Some(now_odds())).unwrap();
    assert_eq!(games.iter().map(|g| (g.away.as_str(), g.home.as_str())).collect::<Vec<_>>(), vec![("UTA", "MTL"), ("CGY", "EDM")]);
    assert!(warnings.iter().any(|w| w.contains("Quebec Nordiques")));
    assert_eq!(warnings, vec!["odds: unknown team name 'Quebec Nordiques' / 'Hartford Whalers'"]);
    let (mtl, edm) = (&games[0], &games[1]);
    assert_eq!(edm.commence_time_utc, "2026-10-09T02:00:00Z");
    assert_eq!(edm.event_id.as_deref(), Some("e1"));
    assert_eq!((edm.bookmaker_count, edm.books.len()), (3, 3));
    assert_eq!((edm.home_ml, edm.away_ml), (Some(-200), Some(170)));
    assert_eq!((edm.total, edm.over_price, edm.under_price), (Some(6.5), Some(-107), Some(-112)));
    assert!(edm.implied_home_total.unwrap() > edm.implied_away_total.unwrap());
    assert!(mtl.home_ml == Some(110) && mtl.implied_home_total < mtl.implied_away_total);
    let d = Value::Object(edm.to_dict(true));
    assert_eq!(d["game_date"], "2026-10-08");
    let back = o::GameOdds::from_dict(d.as_object().unwrap()).unwrap();
    assert_eq!(&back, edm);
    assert_eq!(o::parse_quota(Some(&headers())), Some([("remaining", 498), ("used", 2), ("last", 2)].into_iter().map(|(k, v)| (k.to_string(), v)).collect()));
    let one: Map<String, String> = [("x-requests-remaining".to_string(), "497.0".to_string())].into_iter().collect();
    assert_eq!(o::parse_quota(Some(&one)).unwrap()["remaining"], 497);
    assert_eq!(o::parse_quota(Some(&Map::new())), None);
    let bad: Map<String, String> = [("x-requests-used".to_string(), "n/a".to_string())].into_iter().collect();
    assert_eq!(o::parse_quota(Some(&bad)), None);
}

type Calls = std::rc::Rc<RefCell<Vec<(String, Vec<(String, String)>)>>>;

fn fetch_box(calls: Calls) -> Box<o::FetchJson> {
    Box::new(move |url: &str, params: &[(String, String)]| {
        calls.borrow_mut().push((url.to_string(), params.to_vec()));
        Ok((Value::Array(events()), headers()))
    })
}

fn clock_at(t: DateTime<Utc>) -> Box<dyn Fn() -> DateTime<Utc>> {
    Box::new(move || t)
}

#[test]
fn client_calls_once_per_20h_and_never_stores_key() {
    let tmp = tempfile::tempdir().unwrap();
    let calls: Calls = Default::default();
    let mk = |t: DateTime<Utc>, offline: bool, dir: &Path| {
        o::OddsClient::new(Some(KEY), Some(fetch_box(calls.clone())), None, Some(dir), offline, o::CACHE_TTL_HOURS, Some(clock_at(t)))
    };
    let mut c = mk(now_odds(), false, tmp.path());
    let games = c.nhl_odds().unwrap();
    assert!(games.len() == 2 && calls.borrow().len() == 1 && c.quota.as_ref().unwrap()["remaining"] == 498 && !c.from_cache);
    {
        let cb = calls.borrow();
        let (url, params) = &cb[0];
        let p: Map<String, String> = params.iter().cloned().collect();
        assert!(url == o::ODDS_URL && p["markets"] == "h2h,totals" && p["regions"] == "us");
        assert!(p["oddsFormat"] == "american" && p["apiKey"] == KEY);
    }
    let cache = std::fs::read_to_string(tmp.path().join(o::CACHE_FILE)).unwrap();
    assert!(!cache.contains(KEY) && !format!("{c:?}").contains(KEY));
    assert!(cache.starts_with("{\"fetched_at\":\"2026-10-08T16:00:00Z\",\"region\":\"us\",\"markets\":\"h2h,totals\",\"quota\":{\"remaining\":498,\"used\":2,\"last\":2},\"events\":[{"));
    assert!(cache.contains("Montr\\u00e9al"));

    let mut c2 = mk(now_odds() + Duration::hours(19), false, tmp.path());
    assert_eq!(c2.raw_events().unwrap().len(), 4);
    assert!(calls.borrow().len() == 1 && c2.from_cache);
    assert!(c2.nhl_odds().unwrap().is_empty());
    assert_eq!(c2.quota.as_ref().unwrap().len(), 3);

    let mut c3 = mk(now_odds() + Duration::hours(21), false, tmp.path());
    c3.raw_events().unwrap();
    assert!(calls.borrow().len() == 2 && !c3.from_cache);

    let mut off = mk(now_odds() + Duration::days(5), true, tmp.path());
    off.raw_events().unwrap();
    assert!(calls.borrow().len() == 2 && off.from_cache);
    let mut empty = mk(now_odds(), true, &tmp.path().join("empty"));
    let err = empty.raw_events().unwrap_err();
    assert!(err.downcast_ref::<o::OddsError>().is_some());
}

#[test]
fn errors_never_carry_the_key_and_no_key_is_a_no_op() {
    let tmp = tempfile::tempdir().unwrap();
    let boom: Box<o::FetchJson> = Box::new(|url: &str, params: &[(String, String)]| {
        let key = &params.iter().find(|(k, _)| k == "apiKey").unwrap().1;
        anyhow::bail!("connection failed for {url}?apiKey={key}")
    });
    let mut c = o::OddsClient::new(Some(KEY), Some(boom), None, Some(tmp.path()), false, o::CACHE_TTL_HOURS, None);
    let err = c.nhl_odds().unwrap_err();
    let msg = err.to_string();
    assert!(err.downcast_ref::<o::OddsError>().is_some() && !msg.contains(KEY) && msg.contains("***"));
    assert!(!tmp.path().join(o::CACHE_FILE).exists());

    let calls: Calls = Default::default();
    let mut nokey = o::OddsClient::new(None, Some(fetch_box(calls.clone())), None, Some(tmp.path()), false, o::CACHE_TTL_HOURS, None);
    assert!(!nokey.available() && nokey.nhl_odds().unwrap().is_empty() && nokey.raw_events().unwrap().is_empty());
    assert!(calls.borrow().is_empty());
    assert!(!o::OddsClient::new(Some("  "), None, None, None, false, o::CACHE_TTL_HOURS, None).available());
    let s = fm_core::config::Settings { fm_data_dir: tmp.path().to_path_buf(), ..Default::default() };
    assert!(!o::OddsClient::from_settings(&s, None).available());
}

#[test]
fn archive_dedupe_load_and_team_context() {
    let tmp = tempfile::tempdir().unwrap();
    let (games, _) = o::parse_events(&events(), Some(now_odds())).unwrap();
    let day = NaiveDate::from_ymd_opt(2026, 10, 8).unwrap();
    let quota: o::Quota = [("remaining".to_string(), 498)].into_iter().collect();
    let (p, st) = o::archive_odds(&games, tmp.path(), day, Some(now_odds()), Some(&quota), "us", false).unwrap();
    assert_eq!(st, "written");
    assert_eq!(p, tmp.path().join("archive").join("odds-2026-10-08.json"));
    let before = std::fs::read(&p).unwrap();
    let (_, st2) = o::archive_odds(&games[..1], tmp.path(), day, Some(now_odds() + Duration::hours(1)), None, "us", false).unwrap();
    assert!(st2 == "exists" && std::fs::read(&p).unwrap() == before);
    let snap = o::load_odds(tmp.path(), day).unwrap();
    assert_eq!(snap.header["date"], "2026-10-08");
    assert_eq!(snap.header["quota"], json!({"remaining": 498}));
    assert_eq!(snap.games, games);
    assert!(o::load_odds(tmp.path(), day.succ_opt().unwrap()).is_none());

    let ctx = o::team_context(day, tmp.path(), o::LOOKBACK_DAYS);
    let mut keys: Vec<&String> = ctx.keys().collect();
    keys.sort();
    assert_eq!(keys, vec!["CGY", "EDM", "MTL", "UTA"]);
    let (edm, cgy) = (&ctx["EDM"], &ctx["CGY"]);
    assert!(edm.home && !cgy.home && edm.opponent == "CGY" && cgy.opponent == "EDM");
    assert!(edm.implied_total == games[1].implied_home_total && cgy.implied_total == games[1].implied_away_total);
    assert!(approx(edm.win_prob.unwrap() + cgy.win_prob.unwrap(), 1.0, 1e-4) && edm.as_of == "2026-10-08");
    let mut later_d = games[1].to_dict(true);
    later_d.insert("game_date".into(), json!("2026-10-10"));
    let later = vec![o::GameOdds::from_dict(&later_d).unwrap()];
    o::archive_odds(&later, tmp.path(), NaiveDate::from_ymd_opt(2026, 10, 9).unwrap(), None, None, "us", false).unwrap();
    let d10 = NaiveDate::from_ymd_opt(2026, 10, 10).unwrap();
    let tc = o::team_context(d10, tmp.path(), o::LOOKBACK_DAYS);
    assert_eq!(tc.len(), 2);
    assert_eq!(tc["EDM"].as_of, "2026-10-09");
    assert!(o::team_context(NaiveDate::from_ymd_opt(2026, 11, 1).unwrap(), tmp.path(), o::LOOKBACK_DAYS).is_empty());
}

