#[test]
fn free_only_guard() {
    assert!(is_free_model("openrouter/free") && is_free_model("qwen/qwen3.8-27b:free"));
    assert!(!is_free_model("google/gemini-2.5-flash-lite"));
    let st = settings_with_key(Some("k"));
    let c = LLMClient::new(Some(&st), None, Some("google/gemini-2.5-flash-lite"), None, 60.0);
    assert!(c.free_only);
    let err = c.create(&[("user".into(), "hi".into())], 10, 0.0, false, None).unwrap_err();
    assert!(err.message.contains("non-free"));
    let paid = fm_core::config::Settings { fm_llm_allow_paid: true, ..settings_with_key(Some("k")) };
    assert!(!LLMClient::new(Some(&paid), None, Some("google/gemini-2.5-flash-lite"), None, 60.0).free_only);
    let (s, _) = sdk(vec![]);
    assert!(!LLMClient::new(Some(&st), Some(s), Some("anything/paid"), None, 60.0).free_only);
    // the real client asks OpenRouter for zero-cost routing
    let (s, calls) = sdk(vec![Ok(ChatResponse::text("ok"))]);
    let mut guarded = LLMClient::new(Some(&st), Some(s), None, None, 60.0);
    guarded.free_only = true;
    guarded.complete_text("s", "u", CompleteOpts::default()).unwrap();
    assert_eq!(calls.borrow()[0].body()["provider"], json!({"max_price": {"prompt": 0, "completion": 0}}));
}

#[test]
fn client_side_fallback_on_retryable_error_and_truncation() {
    let (s, calls) = sdk(vec![Err(status(429, "rate limited")), Ok(ChatResponse::text(r#"{"note": "ok"}"#))]);
    let c = LLMClient::new(Some(&settings_with_key(Some("k"))), Some(s), Some("a/primary:free"), Some(vec!["b/backup:free".into()]), 60.0);
    let out = c.complete_text("sys", "user", CompleteOpts { json_mode: true, ..Default::default() }).unwrap();
    assert!(out.contains("ok"));
    assert_eq!(calls.borrow().iter().map(|r| r.model.as_str()).collect::<Vec<_>>(), vec!["a/primary:free", "b/backup:free"]);
    let (s, calls) = sdk(vec![Ok(ChatResponse::text("Trade Quinn")), Ok(ChatResponse::text(&"A".repeat(200)))]);
    let c = LLMClient::new(Some(&settings_with_key(Some("k"))), Some(s), Some("a/p:free"), Some(vec!["b/q:free".into()]), 60.0);
    assert_eq!(c.complete_text("s", "u", CompleteOpts { min_chars: 120, ..Default::default() }).unwrap().len(), 200);
    assert_eq!(calls.borrow().iter().map(|r| r.model.as_str()).collect::<Vec<_>>(), vec!["a/p:free", "b/q:free"]);
    // a finish_reason overrides the length check: "stop" accepts a short answer, "length" is cut off
    let reply = |text: &str, reason: &str| ChatResponse { finish_reason: Some(reason.into()), ..ChatResponse::text(text) };
    let (s, _) = sdk(vec![Ok(reply("Start Sorokin.", "stop"))]);
    let c = LLMClient::new(Some(&settings_with_key(Some("k"))), Some(s), Some("a/p:free"), Some(vec![]), 60.0);
    assert_eq!(c.complete_text("s", "u", CompleteOpts { min_chars: 120, ..Default::default() }).unwrap(), "Start Sorokin.");
    let (s, calls) = sdk(vec![Ok(reply(&"A".repeat(200), "length")), Ok(reply("Start Sorokin.", "stop"))]);
    let c = LLMClient::new(Some(&settings_with_key(Some("k"))), Some(s), Some("a/p:free"), Some(vec!["b/q:free".into()]), 60.0);
    assert_eq!(c.complete_text("s", "u", CompleteOpts { min_chars: 120, ..Default::default() }).unwrap(), "Start Sorokin.");
    assert_eq!(calls.borrow().len(), 2);
    // auth errors do not fall back
    let (s, calls) = sdk(vec![Err(status(401, "no"))]);
    let c = LLMClient::new(None, Some(s), Some("a/p:free"), Some(vec!["b/q:free".into()]), 60.0);
    assert!(c.complete_text("s", "u", CompleteOpts::default()).is_err());
    assert_eq!(calls.borrow().len(), 1);
}

